function songReleaseDateHTML(t){
 const stamp=Number(t.created);if(!Number.isFinite(stamp)||stamp<=0)return '';
 const date=new Date(stamp*1000);if(Number.isNaN(date.getTime()))return '';
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);
 const part=name=>parts.find(p=>p.type===name).value,iso=part('year')+'-'+part('month')+'-'+part('day');
 return '<p class="song-release-date">발매일 <time datetime="'+iso+'">'+iso.replaceAll('-','.')+'</time><small>곡 등록일 기준</small></p>';
}
function karaokeParticipationHTML(t){
 const people=[...new Map((t.cover_participants||[]).map(p=>[p.producer_id,p])).values()];
 return '<div class="karaoke-participation"><button type="button" data-karaoke-covers="'+esc(t.id)+'" aria-expanded="false" aria-controls="covers-'+esc(t.id)+'">'+icon('users')+' 참여 커버 <b>'+number(t.covers||0)+'</b> '+icon('chevron')+'</button><span>'+people.map(p=>'<a href="#producer/'+esc(p.producer_id)+'">'+esc(p.name)+'</a>').join(' · ')+(people.length?' 참여':'첫 커버를 들려주세요')+'</span></div>';
}
function communityConceptCard(t){
 const p=musicPerson(t),own=me?.id===t.user_id,id=esc(t.id),title=esc(t.title),active=liked(t.id);
 const moods=(t.moods||[]).slice(0,2).map(m=>typeof AifectGenres!=='undefined'?AifectGenres.MOODS.find(x=>x.id===m)?.name||m:m);
 const tags=[musicKind(t),...(t.genres||[t.genre]).filter(Boolean).slice(0,1),...moods];
 const like=(cls,count=false)=>'<button type="button" class="'+cls+(active?' is-active':'')+'" data-like="'+id+'" aria-label="'+title+' 좋아요" aria-pressed="'+active+'">'+icon('heart')+(count?'<span data-like-count>'+number(t.likes||0)+'</span>':'')+'</button>';
 return '<article class="music-card community-concept-card" data-music-id="'+id+'"><header><a class="music-author" href="#producer/'+esc(p.id)+'">'+portrait(p,'producer')+'<span><strong>'+esc(p.name)+'</strong><small>'+publicMusicDate(t.created)+' 공개</small></span></a>'+(!own?'<button class="small-button music-follow" data-follow="producer/'+esc(p.id)+'" aria-pressed="'+followed('producer',p.id)+'">'+(followed('producer',p.id)?'팔로잉':'팔로우')+'</button>':'')+'<button class="icon-button community-post-more" data-track-menu="'+id+'" aria-label="'+title+' 더보기">⋯</button></header>'+
 '<p class="community-post-description">'+esc(t.description||'새로운 음악을 공개했어요. 함께 들어보세요.')+'</p><div class="community-song-panel"><div class="community-song-art"><a class="music-art" href="#song/'+id+'" aria-label="'+title+' 곡 상세">'+cover(t)+'</a><button type="button" class="community-art-play" data-play="'+id+'" data-community-toggle aria-label="'+title+' 재생">'+icon('play')+'</button></div><div class="community-song-copy"><div class="community-song-tags">'+tags.map(tag=>'<span>'+esc(tag)+'</span>').join('')+'</div><h3><a href="#song/'+id+'">'+title+'</a></h3>'+(t.kind==='cover'?'<a class="community-original-link" href="#song/'+esc(t.original_id)+'">원곡 · '+esc(t.original_title||t.title)+'</a>':'<div class="community-song-credit">'+credits(t)+'</div>')+
 '<div class="community-playback" data-community-progress="'+id+'" data-duration="'+Number(t.duration||0)+'"><span class="community-playback-time"><span data-community-elapsed>0:00</span> / '+time(t.duration)+'</span></div></div>'+like('community-song-like')+'</div>'+
 '<footer class="music-social-actions"><div class="community-reactions">'+like('text-link',true)+'<a class="text-link" href="#song/'+id+'?comments=1" aria-label="'+title+' 댓글 '+number(t.comments||0)+'개">'+icon('message')+' '+number(t.comments||0)+'</a><span class="community-play-count" aria-label="'+number(t.plays||0)+'회 재생">'+icon('play')+' '+number(t.plays||0)+'</span>'+(!own?giftButton(t):'')+'</div><div class="community-save-actions">'+(musicIsOpenDuet(t)&&!own?'<a class="small-button community-join-duet" href="#sing/'+esc(t.original_id)+'?duet='+id+'">'+icon('mic')+' 듀엣 참여</a>':'')+playlistSaveButton(t)+'</div></footer></article>';
}

function crewDiscoveryCard(c,mine,featured=false){
 const open=!!c.recruiting&&Number(c.members)<Number(c.capacity),tags=String(c.interests||'').split(/[,·#]/).map(s=>s.trim()).filter(Boolean).slice(0,3);
 return '<article class="crew-discover-card'+(featured?' is-featured':'')+'">'+crewPicture(c,'crew-discover-image')+'<div class="crew-discover-copy">'+(featured?'<span class="crew-pick-label">'+(c.match?'취향 추천':'크루 둘러보기')+'</span>':'')+'<h3><a href="#crew/'+esc(c.id)+'">'+esc(c.name)+'</a></h3><p>'+esc(c.description||'함께 음악을 듣고 이야기해요.')+'</p><div class="crew-discover-meta">'+icon('users')+' '+number(c.members)+'명 <b>LV.'+number(c.level)+'</b><small>'+number(c.xp)+' XP</small></div><div class="crew-interest-tags">'+tags.map(s=>'<span>'+esc(s)+'</span>').join('')+'</div></div><footer><span class="crew-recruit-state '+(open?'is-open':'')+'">'+(mine===c.id?'내 크루':open?'모집 중':'모집 마감')+'</span><a href="#crew/'+esc(c.id)+'" class="primary-button">자세히 보기 '+icon('chevron')+'</a></footer></article>';
}
function filterCrewDiscovery(crews,{interest='',recruiting='',level='',scope='',sort='recommended'}={},mine){
 return crews.filter(c=>(!interest||String(c.interests||'').split(/[,·#]/).map(s=>s.trim()).includes(interest))&&(!recruiting||(recruiting==='open')===(!!c.recruiting&&Number(c.members)<Number(c.capacity)))&&(!level||Number(c.level)===Number(level))&&(!scope||c.id===mine)).slice().sort((a,b)=>sort==='recent'?Number(b.created)-Number(a.created):sort==='members'?Number(b.members)-Number(a.members):sort==='level'?Number(b.level)-Number(a.level)||Number(b.xp)-Number(a.xp):Number(b.match||0)-Number(a.match||0)||Number(b.xp||0)-Number(a.xp||0));
}
function crewDiscoveryHTML(d,q=''){
 const crews=d.crews||[],picks=filterCrewDiscovery(crews,{},d.mine).slice(0,3),open=crews.filter(c=>c.recruiting&&Number(c.members)<Number(c.capacity)).slice(0,3),interests=[...new Set(crews.flatMap(c=>String(c.interests||'').split(/[,·#]/).map(s=>s.trim()).filter(Boolean)))].sort(),levels=[...new Set(crews.map(c=>Number(c.level)||1))].sort((a,b)=>a-b);
 return '<div class="crew-discovery-heading">'+heading('크루','함께 듣고, 부르고, 이야기하는 음악 모임')+'<div>'+(d.mine?'<a class="primary-button" href="#crew/'+esc(d.mine)+'">'+icon('users')+' 내 크루 들어가기 '+icon('chevron')+'</a>':'<button class="primary-button" data-create-crew>크루 만들기</button>')+'</div></div>'+communityNavigation('crews')+'<div class="crew-discovery-layout"><div class="crew-discovery-main"><section class="crew-featured-section"><div class="section-heading"><h2>✦ 지금 주목할 만한 크루</h2><span>취향과 음악으로 만나는 모임</span></div><div class="crew-featured-grid">'+(picks.length?picks.map(c=>crewDiscoveryCard(c,d.mine,true)).join(''):'<p class="social-empty">아직 등록된 크루가 없어요. 첫 모임을 만들어보세요.</p>')+'</div></section><div class="crew-discovery-tools"><form id="crew-search" class="crew-discovery-search">'+icon('search')+'<input type="search" name="q" value="'+esc(q)+'" maxlength="80" placeholder="크루명, 관심사로 검색해보세요." aria-label="크루 검색"><button type="submit" class="text-link">검색</button></form><form id="crew-discovery-filters"><select name="interest" aria-label="크루 관심사"><option value="">모든 관심사</option>'+interests.map(s=>'<option>'+esc(s)+'</option>').join('')+'</select><select name="recruiting" aria-label="크루 모집 상태"><option value="">모집 상태</option><option value="open">모집 중</option><option value="closed">모집 마감</option></select><select name="level" aria-label="크루 레벨"><option value="">모든 레벨</option>'+levels.map(n=>'<option value="'+n+'">LV.'+n+'</option>').join('')+'</select><select name="scope" aria-label="크루 범위"><option value="">모든 크루</option><option value="mine" '+(!d.mine?'disabled':'')+'>내 크루</option></select><button type="reset" class="text-link">초기화</button></form></div><div class="section-heading crew-results-heading"><h2>발견할 크루 <span id="crew-discovery-count">'+number(crews.length)+'</span></h2><div><select id="crew-discovery-sort" aria-label="크루 정렬"><option value="recommended">추천순</option><option value="recent">최신순</option><option value="level">레벨 · XP순</option><option value="members">인원순</option></select><button class="small-button" data-crew-layout="grid" aria-label="크루 카드로 보기" aria-pressed="true">▦</button><button class="small-button" data-crew-layout="list" aria-label="크루 목록으로 보기" aria-pressed="false">☰</button></div></div><div id="crew-discovery-results" class="crew-discovery-grid">'+crews.map(c=>crewDiscoveryCard(c,d.mine)).join('')+'</div><p class="field-help">검색 결과는 최대 100개까지 표시해요.</p></div><aside class="social-side-column crew-discovery-side">'+crewRankingSidebarHTML(d.rankings)+'<section class="social-side-card"><h2>✦ 지금 모집 중</h2><div class="crew-recruit-list">'+(open.length?open.map(c=>'<a href="#crew/'+esc(c.id)+'">'+crewPicture(c,'crew-rank-picture')+'<span><strong>'+esc(c.name)+'</strong><small>'+number(c.members)+'명 · LV.'+number(c.level)+'</small></span><b>모집 중</b></a>').join(''):'<p class="field-help">모집 중인 크루가 없어요.</p>')+'</div></section><section class="social-side-card crew-discovery-invite"><h2>음악을 함께 나눠요</h2><p>좋아하는 음악으로 만나고,<br>함께 부르며 크루를 키워보세요.</p><a class="text-link" href="#community/covers">커버 음악 둘러보기 '+icon('chevron')+'</a></section></aside></div>';
}
function bindCrewDiscovery(view){
 if(!view?.crewDiscovery)return;const d=view.crewDiscovery,form=$('#crew-discovery-filters'),results=$('#crew-discovery-results'),sort=$('#crew-discovery-sort');if(!form||!results)return;
 const update=()=>{const options=Object.fromEntries(new FormData(form));options.sort=sort.value;const items=filterCrewDiscovery(d.crews||[],options,d.mine);results.innerHTML=items.length?items.map(c=>crewDiscoveryCard(c,d.mine)).join(''):'<p class="social-empty">조건에 맞는 크루가 없어요. 필터를 바꿔보세요.</p>';$('#crew-discovery-count').textContent=number(items.length);};
 form.onchange=update;form.onsubmit=e=>{e.preventDefault();update();};form.onreset=()=>setTimeout(()=>{if(results.isConnected){sort.value='recommended';update();}},0);sort.onchange=update;
 document.querySelectorAll('[data-crew-layout]').forEach(button=>button.onclick=()=>{results.classList.toggle('is-list',button.dataset.crewLayout==='list');document.querySelectorAll('[data-crew-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));});update();
}
